import React from 'react';
import classNames from 'classnames';

import DetailsListItem, {
  DetailListItemIconSide,
  DetailsListItemType,
} from '../../molecules/detailsListItem';
import './index.less';

export type DetailsListType = {
  items?: DetailsListItemType[];
  className?: string;
  ariaLabel?: string;
  iconsSide?: DetailListItemIconSide;
};

const DetailsList = ({
  items,
  className,
  iconsSide = DetailListItemIconSide.RIGHT,
  ariaLabel,
}: DetailsListType) => (
  <ul className={classNames('right-icons-details-list', className)} aria-label={ariaLabel}>
    {items?.map((item) => (
      <DetailsListItem key={item.title} {...item} iconSide={iconsSide} />
    ))}
  </ul>
);

export default DetailsList;
